begin;
create table if not exists workshop_private.tyres74(id int primary key check(id=1), names jsonb not null, revision int not null);
revoke all on workshop_private.tyres74 from public,anon,authenticated;
alter table workshop_private.tyres74 enable row level security;
create or replace function public.workshop_tyres74(p_names jsonb default null,p_revision int default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare a jsonb;r workshop_private.tyres74%rowtype;begin a:=workshop_private.actor_before30();
if p_names is not null then
if not coalesce((a->>'admin')::boolean,false) then raise exception 'Réservé à l’administrateur';end if;
perform pg_advisory_xact_lock(740074);select * into r from workshop_private.tyres74 where id=1;
if coalesce(r.revision,0) is distinct from p_revision then raise exception 'Catalogue modifié. Ferme puis rouvre l’éditeur.';end if;
if jsonb_typeof(p_names)<>'array' or jsonb_array_length(p_names)>2000 then raise exception 'Liste invalide';end if;
if exists(select 1 from jsonb_array_elements(p_names) x where jsonb_typeof(x)<>'object' or coalesce(x->>'photo','') !~ '^(/pneus74/p[0-9]+-[0-9]+[.]webp)?$' or length(trim(coalesce(x->>'name',''))) not between 1 and 200) or exists(select 1 from jsonb_array_elements(p_names) x group by lower(trim(x->>'name')) having count(*)>1) then raise exception 'Nom vide, trop long ou en double';end if;
insert into workshop_private.tyres74 values(1,p_names,1) on conflict(id) do update set names=excluded.names,revision=workshop_private.tyres74.revision+1;
end if;select * into r from workshop_private.tyres74 where id=1;return jsonb_build_object('names',coalesce(r.names,'[]'),'revision',coalesce(r.revision,0));end $$;
